refentry.refsect1:
&reftitle.changelog;





    &Version;
    &Description;





    8.1.0

     Ora restituisce un'istanza di PgSql\Connection;
     in precedenza veniva restituita una &resource;.

  &reftitle.examples;



    Uso di pg_pconnect


<?php
// Connessione a un database chiamato "mary"
$dbconn = pg_pconnect("dbname=mary");

// Connessione a un database chiamato "mary" su "localhost" alla porta "5432"
$dbconn2 = pg_pconnect("host=localhost port=5432 dbname=mary");

// Connessione a un database chiamato "mary" sull'host "sheep" con nome utente e password
$dbconn3 = pg_pconnect("host=sheep port=5432 dbname=mary user=lamb password=foo");

// Connessione a un database chiamato "test" sull'host "sheep" con nome utente e password
$conn_string = "host=sheep port=5432 dbname=test user=lamb password=bar";
$dbconn4 = pg_pconnect($conn_string);
?>
